using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static int[] TopKFrequent(int[] nums, int k)
    {
        // Step 1: Count frequencies
        Dictionary<int, int> counts = new Dictionary<int, int>();
        foreach (int n in nums)
        {
            if (counts.ContainsKey(n))
                counts[n]++;
            else
                counts[n] = 1;
        }

        // Step 2: Convert to list for sorting
        // We use a custom comparer to handle the tie-breaking logic:
        // 1. Frequency descending
        // 2. Value ascending
        List<KeyValuePair<int, int>> list = new List<KeyValuePair<int, int>>(counts);

        list.Sort(delegate (KeyValuePair<int, int> x, KeyValuePair<int, int> y)
        {
            if (x.Value != y.Value)
            {
                // Higher frequency comes first
                return y.Value.CompareTo(x.Value);
