using System;
using System.Text;
using System.Text.RegularExpressions;

public static class StringExtensions
{
    public static string ToSnakeCase(string name)
    {
        if (string.IsNullOrEmpty(name))
        {
            return name;
        }

        StringBuilder result = new StringBuilder();
        int i = 0;
        int length = name.Length;

        while (i < length)
        {
            char current = name[i];

            if (i > 0 && char.IsUpper(current))
            {
                // Check if we are at a transition: 
                // 1. lower/digit -> Upper (e.g., 'aB' -> 'a_b')
                // 2. Upper -> Upper followed by lower (e.g., 'HTTPR' -> 'http_r' if next is 'e')
                bool isTransition = char.IsLower(name[i - 1]) || char.IsDigit(name[i - 1]);
                bool isAcronymEnd = (i + 1 < length && char.IsLower(name[i + 1]));

                if (isTransition || isAcronymEnd)
                {
                    result.Append('_');
                }
            }

            result.Append(char.ToLowerInvariant(current));
            i++;
        }

        return result.ToString();
    }
}
