function ConvertTo-TitleCase {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true, ValueFromPipeline = $true)]
        [string]$Text
    )

    process {
        $TextInfo = (Get-Culture).TextInfo
        # Regex splits by word boundaries but keeps the delimiters (whitespace) in the array
        # This preserves original spacing/tabs/newlines
        $parts = [regex]::Split($Text, '(\s+)')

        $result = foreach ($part in $parts) {
            if ($part -match '\S') {
                # Convert word to lowercase first to ensure "WORLD" -> "World"
                # Then apply TitleCase via TextInfo
                $TextInfo.ToTitleCase($part.ToLower())
            }
            else {
                # It's whitespace, return as is
                $part
            }
        }

        $result -join ''
    }
}
